const e={title_add:"Adicionar uma CLI tua",title_edit:"Editar esta CLI",description:"Qualquer CLI de terminal interativa pode correr num painel aqui. Dá-lhe um nome e o comando que a inicia, e ela aparece em todo o lado onde aparecem as integradas.",close:"Fechar",cancel:"Cancelar",save:"Guardar",save_add:"Adicionar CLI",saving:"A guardar…",name:"Nome",name_placeholder:"p. ex. Aider",name_hint:"O que vais ver nos seletores e dizer em voz alta.",command:"Comando",command_placeholder:"aider",command_hint:"Exatamente o que escreverias num terminal para a iniciar.",command_shell_hint:"Isto corre através de uma shell, porque o comando tem mais do que um programa. O painel fecha quando a linha inteira terminar.",description_label:"Descrição",optional:"Opcional",description_placeholder:"Uma linha a explicar o que é esta CLI.",at_reference:"Escrever ficheiros largados como @caminho",at_reference_hint:"A maioria das CLIs de programação modernas lê @caminho como um ficheiro a abrir. Desativa isto e os caminhos são colados entre aspas.",threads_title:"Executar em threads (opcional)",headless_command:"Comando headless",headless_command_hint:"Permite que esta CLI apareça também como fornecedor nos threads do IDE agêntico. Usa {prompt} onde vai a mensagem; se o omitires, a mensagem é enviada por stdin. A resposta é o que o comando imprime.",headless_resume:"Comando de retoma",headless_resume_hint:"Usado nos turnos seguintes. {session} é substituído pelo id da conversa. Deixa vazio para começar de novo em cada turno.",pick_logo:"Escolher um logótipo",remove_logo:"Remover o logótipo",remove_logo_short:"Remover",logo_label:"Logótipo"},a={custom_cli:e};export{e as custom_cli,a as default};
